def parse_value(kind, field):
    if field == "":
        return None
    if kind == "INT":
        return int(field)
    if kind == "DATE":
        return day_number(field)
    if kind == "BOOL":
        return field == "true"
    return field
def value_text(kind, value, null="NULL"):
    if value is None:
        return null
    if kind == "DATE":
        return (EPOCH + timedelta(days=value)).isoformat()
    if kind == "BOOL":
        return "true" if value else "false"
    return str(value)
